use super::*;

/// The name a definition node declares. One implementation covers both grammars because both spell it
/// as a `name` FIELD: Rust's `function_item`, TypeScript's `function_declaration`, and the
/// `variable_declarator` an arrow const is bound by.
///
/// The kind guard is what the TypeScript arm needs and Rust pays nothing for. A `variable_declarator`'s
/// `name` may be a DESTRUCTURING PATTERN — `const { parse, format } = grammar` — whose text is
/// `{ parse, format }`, not an identifier. Reading that as a function name would mint a leaf nothing can
/// extract. Rust's `function_item` name is always an `identifier`, so the guard never fires there.
pub(crate) fn fn_name(node: Node, src: &[u8]) -> Option<String> {
    let name = node.child_by_field_name("name")?;
    if name.kind() != "identifier" {
        return None;
    }
    Some(name.utf8_text(src).unwrap_or_default().to_string())
}
